using FluentAssertions;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.CSharp.Syntax;
using Microsoft.CodeAnalysis.Testing;

namespace Receipts.GeneratedTests;

public class ExcludeFromCodeCoverageFrameworkTests
{
    [Fact] public async Task Resolver_HasActiveAttribute_WhenNetFrameworkSymbolIsDefined()
    {
        const string source = """
            using MessagePack;

            [GeneratedMessagePackResolver]
            public partial class TestResolver
            {
            }
            """;

        var parseOptions = new CSharpParseOptions(LanguageVersion.Latest, preprocessorSymbols: new[] { "NETFRAMEWORK" });
        ImmutableArray<MetadataReference> references = await ReferenceAssemblies.Net.Net80.ResolveAsync(LanguageNames.CSharp, CancellationToken.None);
        references = references.AddRange(ReferencesHelper.GetReferences(ReferencesSet.MessagePack));

        CSharpCompilation compilation = CSharpCompilation.Create(
            "Receipts",
            new[] { CSharpSyntaxTree.ParseText(source, parseOptions) },
            references,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));

        GeneratorDriver driver = CSharpGeneratorDriver.Create(
            generators: new[] { new MessagePack.SourceGenerator.MessagePackGenerator().AsSourceGenerator() },
            parseOptions: parseOptions);
        driver = driver.RunGeneratorsAndUpdateCompilation(compilation, out _, out _, CancellationToken.None);

        bool hasActiveAttribute = driver.GetRunResult().GeneratedTrees
            .SelectMany(tree => tree.GetRoot().DescendantNodes().OfType<AttributeSyntax>())
            .Any(attribute => attribute.Name.ToString() == "global::System.Diagnostics.CodeAnalysis.ExcludeFromCodeCoverage");

        hasActiveAttribute.Should().BeTrue(".NET Framework 4.x provides ExcludeFromCodeCoverageAttribute, so NETFRAMEWORK must not suppress it");
    }
}
